// bookIDs is the books' ids, upper case as 5etools writes them.
func bookIDs(books []compendium.Book) string {
	ids := make([]string, len(books))
	for i, b := range books {
		ids[i] = strings.ToUpper(b.ID)
	}
	return strings.Join(ids, ", ")
}

